package com.troday.api.service;
import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class ResidentService {
 private final AccountService accounts; private final ContractRepository contracts; private final RoomTenantRepository members; private final OccupantJoinRequestRepository joins; private final RepresentativeHistoryRepository history;
 public ResidentService(AccountService a,ContractRepository c,RoomTenantRepository m,OccupantJoinRequestRepository j,RepresentativeHistoryRepository h){accounts=a;contracts=c;members=m;joins=j;history=h;}
 public ApiResponseDto<?> residents(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);return ok("GET",members.findAll().stream().filter(x->contracts.findById(x.getContractId()).map(c->Objects.equals(c.getLandlordId(),me)).orElse(false)).map(this::memberData).toList());}
 public ApiResponseDto<?> contractMembers(HttpServletRequest r,Long cid){access(r,cid);return ok("GET",members.findAll().stream().filter(x->cid.equals(x.getContractId())).map(this::memberData).toList());}
 public ApiResponseDto<?> export(HttpServletRequest r){return residents(r);}
 public ApiResponseDto<?> joinList(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);String status=r.getParameter("status");return ok("GET",joins.findAll().stream().filter(x->status==null||status.equals(x.getStatus())).filter(x->x.getApplicantId().equals(me)||x.getRequestedById().equals(me)||contracts.findById(x.getContractId()).map(c->Objects.equals(c.getLandlordId(),me)).orElse(false)).map(this::joinData).toList());}
 @Transactional public ApiResponseDto<?> createJoin(HttpServletRequest r,JsonNode b){Long requester=accounts.authenticatedUserId(r);Long cid=requiredLong(b,"contractId"),applicant=requiredLong(b,"applicantId");Contract c=access(r,cid);if(!"ACTIVE".equals(c.getStatus())&&!"CONFIRMED".equals(c.getStatus()))throw conflict("Hợp đồng chưa sẵn sàng thêm người");if(!Objects.equals(c.getViewingTenantId(),requester))throw forbidden("Chỉ đại diện mới được đề nghị thêm người");if(requester.equals(applicant))throw bad("applicantId phải khác người đề nghị");if(joins.findByContractIdOrderByIdDesc(cid).stream().anyMatch(x->x.getApplicantId().equals(applicant)&&Set.of("PENDING_CONSENT","PENDING_LANDLORD","APPROVED").contains(x.getStatus())))throw conflict("Đã có yêu cầu đang mở");OccupantJoinRequest x=new OccupantJoinRequest();x.setContractId(cid);x.setApplicantId(applicant);x.setRequestedById(requester);x.setRepresentativeRoomTenantId(c.getRepresentativeRoomTenantId());x.setPlannedMoveInDate(date(b,"plannedMoveInDate"));x.setMessage(text(b,"message"));return ok("POST",joinData(joins.save(x)));}
 @Transactional public ApiResponseDto<?> consent(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);OccupantJoinRequest x=join(id);if(!Set.of("PENDING_CONSENT","PENDING_LANDLORD").contains(x.getStatus()))throw conflict("Yêu cầu không còn chờ consent");if(!b.path("consent").asBoolean())return cancel(r,id,b);if(me.equals(x.getRequestedById())){x.setRepresentativeConsentedById(me);x.setRepresentativeConsentedAt(LocalDateTime.now());}else if(me.equals(x.getApplicantId())){x.setApplicantConsentedById(me);x.setApplicantConsentedAt(LocalDateTime.now());}else throw forbidden("Không thuộc yêu cầu này");if(x.getRepresentativeConsentedById()!=null&&x.getApplicantConsentedById()!=null)x.setStatus("PENDING_LANDLORD");return ok("POST",joinData(joins.save(x)));}
 @Transactional public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);OccupantJoinRequest x=join(id);if(!x.getRequestedById().equals(me)&&!x.getApplicantId().equals(me))throw forbidden("Không có quyền hủy");if(!Set.of("PENDING_CONSENT","PENDING_LANDLORD").contains(x.getStatus()))throw conflict("Yêu cầu không thể hủy");x.setStatus("CANCELLED");x.setCancelledById(me);x.setCancelledAt(LocalDateTime.now());x.setCancellationReason(text(b,"reason"));return ok("POST",joinData(joins.save(x)));}
 @Transactional public ApiResponseDto<?> approve(HttpServletRequest r,Long id){Long owner=accounts.authenticatedUserId(r);OccupantJoinRequest x=join(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được duyệt");if(!"PENDING_LANDLORD".equals(x.getStatus()))throw conflict("Yêu cầu chưa đủ consent");x.setStatus("APPROVED");x.setReviewedById(owner);x.setReviewedAt(LocalDateTime.now());x.setHoldExpiresAt(LocalDateTime.now().plusHours(48));return ok("POST",joinData(joins.save(x)));}
 @Transactional public ApiResponseDto<?> reject(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);OccupantJoinRequest x=join(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được từ chối");if(!"PENDING_LANDLORD".equals(x.getStatus()))throw conflict("Yêu cầu chưa đủ consent");x.setStatus("REJECTED");x.setReviewedById(owner);x.setReviewedAt(LocalDateTime.now());x.setRejectionReason(text(b,"reason"));if(x.getRejectionReason().isBlank())throw bad("reason là bắt buộc");return ok("POST",joinData(joins.save(x)));}
 @Transactional public ApiResponseDto<?> cancelHold(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);OccupantJoinRequest x=join(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được hủy giữ chỗ");if(!"APPROVED".equals(x.getStatus()))throw conflict("Yêu cầu không ở trạng thái giữ chỗ");x.setStatus("CANCELLED");x.setCancelledById(owner);x.setCancelledAt(LocalDateTime.now());x.setCancellationReason(text(b,"reason"));return ok("POST",joinData(joins.save(x)));}
 @Transactional public ApiResponseDto<?> complete(HttpServletRequest r,Long id){Long owner=accounts.authenticatedUserId(r);OccupantJoinRequest x=join(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được hoàn tất vào ở");if(!"APPROVED".equals(x.getStatus())||x.getHoldExpiresAt().isBefore(LocalDateTime.now()))throw conflict("Giữ chỗ đã hết hạn hoặc không hợp lệ");RoomTenant m=new RoomTenant();m.setContractId(c.getId());m.setRoomId(c.getRoomId());m.setTenantId(x.getApplicantId());m.setFullName("Tenant "+x.getApplicantId());m.setStatus("ACTIVE");m.setIntakeSource("APPROVED_JOIN");m.setJoinRequestId(x.getId());m.setPlannedMoveInDate(x.getPlannedMoveInDate());m.setMoveInDate(x.getPlannedMoveInDate());m.setMoveInConfirmedById(owner);m.setMoveInConfirmedAt(LocalDateTime.now());m=members.save(m);x.setStatus("COMPLETED");x.setCompletedRoomTenantId(m.getId());x.setCompletedAt(LocalDateTime.now());return ok("POST",Map.of("request",joinData(joins.save(x)),"member",memberData(m)));}
 @Transactional public ApiResponseDto<?> moveOut(HttpServletRequest r,Long cid,Long mid,JsonNode b){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được ghi nhận rời");RoomTenant m=members.findById(mid).filter(x->cid.equals(x.getContractId())).orElseThrow(()->notFound("Không tìm thấy thành viên"));if(!"ACTIVE".equals(m.getStatus()))throw conflict("Thành viên chưa active");LocalDate d=b!=null&&b.hasNonNull("moveOutDate")?date(b,"moveOutDate"):LocalDate.now();m.setStatus("LEFT");m.setMoveOutDate(d);m.setMoveOutConfirmedById(owner);m.setMoveOutConfirmedAt(LocalDateTime.now());return ok("POST",Map.of("member",memberData(members.save(m)),"contractStatus",c.getStatus(),"roomStatus","AVAILABLE"));}
 public ApiResponseDto<?> candidates(HttpServletRequest r,Long cid){Contract c=access(r,cid);if(!Objects.equals(c.getLandlordId(),accounts.authenticatedUserId(r)))throw forbidden("Chỉ chủ trọ được xem");return ok("GET",members.findAll().stream().filter(x->cid.equals(x.getContractId())&&"ACTIVE".equals(x.getStatus())&&x.getTenantId()!=null&&!x.getId().equals(c.getRepresentativeRoomTenantId())).map(this::memberData).toList());}
 public ApiResponseDto<?> representativeHistory(HttpServletRequest r,Long cid){access(r,cid);return ok("GET",history.findByContractIdOrderByStartedAtDesc(cid).stream().map(this::historyData).toList());}
 @Transactional public ApiResponseDto<?> handover(HttpServletRequest r,Long cid,JsonNode b){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được bàn giao");Long departing=requiredLong(b,"departingMemberId"),successor=requiredLong(b,"successorMemberId");if(!b.path("consentRecorded").asBoolean())throw bad("consentRecorded là bắt buộc");RoomTenant old=members.findById(departing).orElseThrow(()->notFound("Không tìm thấy đại diện cũ"));RoomTenant next=members.findById(successor).orElseThrow(()->notFound("Không tìm thấy đại diện mới"));if(!cid.equals(old.getContractId())||!cid.equals(next.getContractId())||!"ACTIVE".equals(next.getStatus()))throw conflict("Người kế nhiệm không hợp lệ");old.setStatus("LEFT");old.setMoveOutDate(LocalDate.now());old.setMoveOutConfirmedById(owner);old.setMoveOutConfirmedAt(LocalDateTime.now());members.save(old);LocalDateTime now=LocalDateTime.now();for(RepresentativeHistory current:history.findByContractIdOrderByStartedAtDesc(cid))if(current.isCurrent()){current.setCurrent(false);current.setEndedAt(now);history.save(current);}c.setRepresentativeRoomTenantId(next.getId());contracts.save(c);RepresentativeHistory h=new RepresentativeHistory();h.setContractId(cid);h.setRoomTenantId(next.getId());h.setNameSnapshot(next.getFullName());h.setEventType("HANDOVER");h.setStartedAt(now);h.setCurrent(true);h.setRecordedById(owner);h.setReason(text(b,"reason"));h.setConsentMethod("LANDLORD_RECORDED");history.save(h);return ok("POST",Map.of("contractId",cid,"representativeMemberId",next.getId()));}
 private Contract access(HttpServletRequest r,Long cid){Long me=accounts.authenticatedUserId(r);Contract c=contracts.findById(cid).orElseThrow(()->notFound("Không tìm thấy hợp đồng"));if(!Objects.equals(c.getLandlordId(),me)&&!Objects.equals(c.getViewingTenantId(),me))throw forbidden("Không có quyền");return c;}private OccupantJoinRequest join(Long id){return joins.findById(id).orElseThrow(()->notFound("Không tìm thấy yêu cầu"));}private LocalDate date(JsonNode b,String k){try{return LocalDate.parse(text(b,k));}catch(Exception e){throw bad(k+" không hợp lệ");}}private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();}private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";}
 private Map<String,Object> memberData(RoomTenant m){Map<String,Object>x=new LinkedHashMap<>();x.put("id",m.getId());x.put("contractId",m.getContractId());x.put("roomId",m.getRoomId());x.put("tenantId",m.getTenantId());x.put("fullName",m.getFullName());x.put("status",m.getStatus());x.put("plannedMoveInDate",m.getPlannedMoveInDate());x.put("moveInDate",m.getMoveInDate());x.put("moveOutDate",m.getMoveOutDate());return x;}private Map<String,Object> joinData(OccupantJoinRequest x){Map<String,Object>m=new LinkedHashMap<>();m.put("id",x.getId());m.put("contractId",x.getContractId());m.put("applicantId",x.getApplicantId());m.put("requestedById",x.getRequestedById());m.put("status",x.getStatus());m.put("plannedMoveInDate",x.getPlannedMoveInDate());m.put("holdExpiresAt",x.getHoldExpiresAt());m.put("completedRoomTenantId",x.getCompletedRoomTenantId());return m;}private Map<String,Object> historyData(RepresentativeHistory x){return Map.of("id",x.getId(),"roomTenantId",x.getRoomTenantId(),"nameSnapshot",x.getNameSnapshot(),"eventType",x.getEventType(),"startedAt",x.getStartedAt(),"endedAt",x.getEndedAt(),"reason",x.getReason());}private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
